window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9cfa446ca6dd0a53"]={"versions": [{"id": "FIG-9cfa446ca6dd0a53", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribute:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ receiverCapability: ReceiverCapabilityEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger mit Attribut <code>+ queueLength: PositiveInteger</code>.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ disableEndToEndCheck: Boolean</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSize: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverCapabilityEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>dataUpdatePeriod</code> definiert die erwartete zyklische Aktualisierungsrate des Datenstroms.\n</li><li><code>queueLength</code> legt die Pufferkapazität für ankommende Datenpakete fest, bevor Überläufe behandelt werden müssen.\n</li><li>Die E2E-Zustandsmaschine wertet Fenstergrößen (<code>windowSize</code>) und Schwellwerte fehlerhafter bzw. gültiger Botschaften (<code>maxErrorState...</code>, <code>minOkState...</code>) über Sequenzzähler (<code>maxDeltaCounter</code>) aus, um zwischen Initial-, Valid- und Invalid-Zuständen der Datenintegrität zu wechseln.\n</li><li><code>disableEndToEndCheck</code> ermöglicht die Deaktivierung der E2E-Prüfung zur Laufzeit.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Festlegung der Konfigurationsmöglichkeiten für R-Ports der Adaptive Platform.\n</li><li>Modellierung erfordert bei Vorhandensein eines Empfangsdatenpunkts die Zuweisung eines passenden <code>AutosarDataPrototype</code> (<code>dataElement</code>).\n</li><li>Gepufferte Empfänger müssen über <code>QueuedReceiverComSpec</code> instanziiert werden; <code>queueLength</code> ist zwingend anzugeben.\n</li><li>E2E-Konfigurationen müssen über <code>EndToEndTransformationComSpecProps</code> definiert werden, falls End-to-End-Absicherung auf der Datenschnittstelle aktiv ist.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f636d33343098610", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribute:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ receiverCapability: ReceiverCapabilityEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger mit Attribut <code>+ queueLength: PositiveInteger</code>.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ disableEndToEndCheck: Boolean</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSize: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverCapabilityEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>dataUpdatePeriod</code> definiert die erwartete zyklische Aktualisierungsrate des Datenstroms.\n</li><li><code>queueLength</code> legt die Pufferkapazität für ankommende Datenpakete fest, bevor Überläufe behandelt werden müssen.\n</li><li>Die E2E-Zustandsmaschine wertet Fenstergrößen (<code>windowSize</code>) und Schwellwerte fehlerhafter bzw. gültiger Botschaften (<code>maxErrorState...</code>, <code>minOkState...</code>) über Sequenzzähler (<code>maxDeltaCounter</code>) aus, um zwischen Initial-, Valid- und Invalid-Zuständen der Datenintegrität zu wechseln.\n</li><li><code>disableEndToEndCheck</code> ermöglicht die Deaktivierung der E2E-Prüfung zur Laufzeit.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Festlegung der Konfigurationsmöglichkeiten für R-Ports der Adaptive Platform.\n</li><li>Modellierung erfordert bei Vorhandensein eines Empfangsdatenpunkts die Zuweisung eines passenden <code>AutosarDataPrototype</code> (<code>dataElement</code>).\n</li><li>Gepufferte Empfänger müssen über <code>QueuedReceiverComSpec</code> instanziiert werden; <code>queueLength</code> ist zwingend anzugeben.\n</li><li>E2E-Konfigurationen müssen über <code>EndToEndTransformationComSpecProps</code> definiert werden, falls End-to-End-Absicherung auf der Datenschnittstelle aktiv ist.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4949615ec489d73e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribute:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ receiverCapability: ReceiverCapabilityEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger mit Attribut <code>+ queueLength: PositiveInteger</code>.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverCapabilityEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>dataUpdatePeriod</code> definiert die erwartete zyklische Aktualisierungsrate des Datenstroms.\n</li><li><code>queueLength</code> legt die Pufferkapazität für ankommende Datenpakete fest.\n</li><li>Die E2E-Zustandsmaschine verwendet separate Schiebefenster für die Zustände Init, Valid und Invalid (<code>windowSizeInit</code>, <code>windowSizeInvalid</code>, <code>windowSizeValid</code>). Zustandsübergänge werden anhand von Schwellwerten fehlerhafter bzw. gültiger Botschaften (<code>maxErrorState...</code>, <code>minOkState...</code>) und Sequenzzählerabweichungen (<code>maxDeltaCounter</code>) evaluiert.\n</li><li><code>clearFromValidToInvalid</code> steuert, ob beim Übergang von Valid nach Invalid alte Pufferinhalte verworfen werden.\n</li><li><code>disableEndToEndCheck</code> steuert die Deaktivierung der E2E-Prüfung.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Konfiguration der E2E-Überwachungsfenster muss getrennt für die jeweiligen Zustände (<code>windowSizeInit</code>, <code>windowSizeInvalid</code>, <code>windowSizeValid</code>) vorgenommen werden.\n</li><li>Bei Aktivierung von <code>clearFromValidToInvalid</code> ist sicherzustellen, dass die Applikation das Verwerfen ungültiger Daten konsistent verarbeitet.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-13d52517bc4b754e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger mit Attribut <code>+ queueLength: PositiveInteger [0..1]</code>.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> signalisiert die Empfangsbereitschaft bzw. Absicht der Applikation für den Port (<code>willReceive</code> vs. <code>wontReceive</code>).\n</li><li><code>queueLength</code> legt optional die Puffergröße für ankommende Datenpakete fest.\n</li><li>Die E2E-Zustandsmaschine kann über <code>disableEndToEndStateMachine</code> vollständig umgangen oder über <code>disableEndToEndCheck</code> die Prüfung deaktiviert werden.\n</li><li>Bei aktiver E2E-Prüfung evaluieren zustandsspezifische Schiebefenster (<code>windowSizeInit</code>, <code>windowSizeInvalid</code>, <code>windowSizeValid</code>) zusammen mit Fehler- und Erfolgsschwellwerten (<code>maxErrorState...</code>, <code>minOkState...</code>) die Gültigkeit der Daten.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> ersetzt vorherige Empfangsfähigkeitsdeklarationen; <code>dataUpdatePeriod</code> entfällt auf Ebene von <code>ReceiverComSpec</code>.\n</li><li><code>queueLength</code> an <code>QueuedReceiverComSpec</code> ist optional modellierbar.\n</li><li>E2E-Absicherung bietet differenzierte Schalter: Neben der Prüfung selbst (<code>disableEndToEndCheck</code>) kann auch die E2E-Zustandsmaschine separat deaktiviert werden (<code>disableEndToEndStateMachine</code>).\n</li><li>Anwenderspezifische Transformationsparameter können über <code>UserDefinedTransformationComSpecProps</code> in das Metamodell eingebunden werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cba953bf12096b0c", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n Besitzt per Komposition <code>+receptionProps 0..1</code> eine Spezifikation vom Typ <code>ReceptionComSpecProps</code>.\n</li></ul>\n</li><li><code>ReceptionComSpecProps</code>: Definiert Empfangsparameter mit Attributen:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ timeout: TimeValue [0..1]</code>\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger (ohne eigene Attribute).\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> steuert die Empfangsbereitschaft des Endpunkts.\n</li><li><code>dataUpdatePeriod</code> in <code>ReceptionComSpecProps</code> definiert das erwartete Sendeintervall; <code>timeout</code> legt die maximale Wartezeit bis zum Ausbleiben einer Botschaft fest (Deadline-Monitoring).\n</li><li>E2E-Überwachung und Zustandstransitionen erfolgen anhand der Konfiguration in <code>EndToEndTransformationComSpecProps</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeitliche Empfangsparameter (<code>dataUpdatePeriod</code>, <code>timeout</code>) werden gekapselt in <code>ReceptionComSpecProps</code> über die Kompositionsrolle <code>+receptionProps 0..1</code> an <code>ReceiverComSpec</code> definiert.\n</li><li><code>QueuedReceiverComSpec</code> enthält keine explizite <code>queueLength</code> mehr im Modell.\n</li><li>Deadlines und Timeout-Mechanismen lassen sich explizit über <code>ReceptionComSpecProps.timeout</code> konfigurieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-04f47afcf82a5716", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n Besitzt per Komposition <code>+receptionProps 0..1</code> eine Spezifikation vom Typ <code>ReceptionComSpecProps</code>.\n</li></ul>\n</li><li><code>ReceptionComSpecProps</code>: Definiert Empfangsparameter mit Attributen:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ timeout: TimeValue [0..1]</code>\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger (ohne eigene Attribute).\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> steuert die Empfangsbereitschaft des Endpunkts.\n</li><li><code>dataUpdatePeriod</code> in <code>ReceptionComSpecProps</code> definiert das erwartete Sendeintervall; <code>timeout</code> legt die maximale Wartezeit bis zum Ausbleiben einer Botschaft fest (Deadline-Monitoring).\n</li><li>E2E-Überwachung und Zustandstransitionen erfolgen anhand der Konfiguration in <code>EndToEndTransformationComSpecProps</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeitliche Empfangsparameter (<code>dataUpdatePeriod</code>, <code>timeout</code>) werden gekapselt in <code>ReceptionComSpecProps</code> über die Kompositionsrolle <code>+receptionProps 0..1</code> an <code>ReceiverComSpec</code> definiert.\n</li><li><code>QueuedReceiverComSpec</code> enthält keine explizite <code>queueLength</code> mehr im Modell.\n</li><li>Deadlines und Timeout-Mechanismen lassen sich explizit über <code>ReceptionComSpecProps.timeout</code> konfigurieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-49c3b18141e0759b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>. Die Kompositionskante ist mit dem Stereotyp <code>«atpSplitable»</code> versehen.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n Besitzt per Komposition <code>+receptionProps 0..1</code> eine Spezifikation vom Typ <code>ReceptionComSpecProps</code>.\n</li></ul>\n</li><li><code>ReceptionComSpecProps</code>: Definiert Empfangsparameter mit Attributen:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ timeout: TimeValue [0..1]</code>\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> steuert die Empfangsbereitschaft des Endpunkts.\n</li><li><code>dataUpdatePeriod</code> in <code>ReceptionComSpecProps</code> definiert das erwartete Sendeintervall; <code>timeout</code> legt die maximale Wartezeit bis zum Ausbleiben einer Botschaft fest (Deadline-Monitoring).\n</li><li>E2E-Überwachung und Zustandstransitionen erfolgen anhand der Konfiguration in <code>EndToEndTransformationComSpecProps</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Durch das Stereotyp <code>«atpSplitable»</code> an der Rolle <code>requiredComSpec</code> dürfen Kommunikationsspezifikationen desselben Ports über mehrere ARXML-Dateien bzw. Partitionsfragmente verteilt definiert und zusammengeführt werden.\n</li><li>Zeitliche Empfangsparameter verbleiben in <code>ReceptionComSpecProps</code>.\n</li><li>Transformations- und E2E-Konfigurationen sind unverändert über die jeweiligen Spezialisierungen von <code>TransformationComSpecProps</code> zu pflegen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5e5d9750141e93df", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>. Die Kompositionskante ist mit dem Stereotyp <code>«atpSplitable»</code> versehen.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>).\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>.\n Besitzt per Komposition <code>+receptionProps 0..1</code> eine Spezifikation vom Typ <code>ReceptionComSpecProps</code>.\n</li></ul>\n</li><li><code>ReceptionComSpecProps</code>: Definiert Empfangsparameter mit Attributen:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ timeout: TimeValue [0..1]</code>\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert die Literale <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> steuert die Empfangsbereitschaft des Endpunkts.\n</li><li><code>dataUpdatePeriod</code> in <code>ReceptionComSpecProps</code> definiert das erwartete Sendeintervall; <code>timeout</code> legt die maximale Wartezeit bis zum Ausbleiben einer Botschaft fest (Deadline-Monitoring).\n</li><li>E2E-Überwachung und Zustandstransitionen erfolgen anhand der Konfiguration in <code>EndToEndTransformationComSpecProps</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Durch das Stereotyp <code>«atpSplitable»</code> an der Rolle <code>requiredComSpec</code> dürfen Kommunikationsspezifikationen desselben Ports über mehrere ARXML-Dateien bzw. Partitionsfragmente verteilt definiert und zusammengeführt werden.\n</li><li>Zeitliche Empfangsparameter verbleiben in <code>ReceptionComSpecProps</code>.\n</li><li>Transformations- und E2E-Konfigurationen sind unverändert über die jeweiligen Spezialisierungen von <code>TransformationComSpecProps</code> zu pflegen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-638d3e8d088afa49", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (<code>ReceiverComSpec</code>) auf der AUTOSAR Adaptive Platform im Rahmen der AUTOSAR Manifest Specification. Das Diagramm modelliert die strukturellen Eigenschaften, Pufferungseinstellungen sowie End-to-End-Absicherungsmechanismen für empfangsseitige Datenendpunkte an Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Bildet die Port-Schnittstelle und enthält per Komposition <code>+requiredComSpec 0..*</code> Instanzen von <code>RPortComSpec</code>. Die Kompositionskante ist mit dem Stereotyp <code>«atpSplitable»</code> versehen.\n</li><li><code>RPortComSpec</code>: Abstrakte Basisklasse für empfangsseitige Port-Kommunikationsspezifikationen.\n</li><li><code>ReceiverComSpec</code>: Spezialisiert <code>RPortComSpec</code>. Attribut:\n<ul class=\"fig-list\"><li><code>+ receiverIntent: ReceiverIntentEnum [0..1]</code>\n Besitzt eine gerichtete Assoziation <code>+dataElement 0..1</code> auf <code>AutosarDataPrototype</code> (Generalisierung von <code>VariableDataPrototype</code>, abgeleitet von <code>DataPrototype</code>), ausgezeichnet mit dem Stereotyp <code>«atpIdentityContributor»</code>.\n Besitzt per Komposition <code>+transformationComSpecProps 0..*</code> Konfigurationseigenschaften vom Typ <code>TransformationComSpecProps</code>, ausgezeichnet mit dem Stereotyp <code>«atpSplitable»</code>.\n Besitzt per Komposition <code>+receptionProps 0..1</code> eine Spezifikation vom Typ <code>ReceptionComSpecProps</code>.\n</li></ul>\n</li><li><code>ReceptionComSpecProps</code>: Definiert Empfangsparameter mit Attributen:\n<ul class=\"fig-list\"><li><code>+ dataUpdatePeriod: TimeValue [0..1]</code>\n</li><li><code>+ timeout: TimeValue [0..1]</code>\n</li></ul>\n</li><li><code>QueuedReceiverComSpec</code>: Spezialisiert <code>ReceiverComSpec</code> für gepufferte Empfänger.\n</li><li><code>TransformationComSpecProps</code>: Spezialisiert <code>Describable</code>.\n</li><li><code>UserDefinedTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> für anwenderspezifische Transformationskonfigurationen.\n</li><li><code>EndToEndTransformationComSpecProps</code>: Spezialisiert <code>TransformationComSpecProps</code> zur E2E-Überwachung mit Attributen:\n<ul class=\"fig-list\"><li><code>+ clearFromValidToInvalid: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndCheck: Boolean [0..1]</code>\n</li><li><code>+ disableEndToEndStateMachine: Boolean [0..1]</code>\n</li><li><code>+ maxDeltaCounter: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ maxErrorStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInit: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ minOkStateValid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInit: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeInvalid: PositiveInteger [0..1]</code>\n</li><li><code>+ windowSizeValid: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><code>ReceiverIntentEnum</code> (Enumeration): Definiert unter dem Bereich <em>literals</em> die Werte <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzpfade. Zur Laufzeit steuern die deklarierten Parameter das Empfangsverhalten der Kommunikationsschicht:</p>\n<ul class=\"fig-list\"><li><code>receiverIntent</code> steuert die Empfangsbereitschaft des Endpunkts.\n</li><li><code>dataUpdatePeriod</code> in <code>ReceptionComSpecProps</code> definiert das erwartete Sendeintervall; <code>timeout</code> legt die maximale Wartezeit bis zum Ausbleiben einer Botschaft fest (Deadline-Monitoring).\n</li><li>E2E-Überwachung und Zustandstransitionen erfolgen anhand der Konfiguration in <code>EndToEndTransformationComSpecProps</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Durch das Stereotyp <code>«atpSplitable»</code> an den Rollen <code>requiredComSpec</code> und <code>transformationComSpecProps</code> dürfen Kommunikationsspezifikationen sowie Transformationskonfigurationen über mehrere ARXML-Dateien bzw. Partitionsfragmente verteilt definiert und zusammengeführt werden.\n</li><li>Durch das Stereotyp <code>«atpIdentityContributor»</code> an der Assoziation <code>+dataElement</code> trägt die Referenz auf das Datenelement zur Identitätsbildung der <code>ReceiverComSpec</code> im Modell bei.\n</li><li>Zeitliche Empfangsparameter in <code>ReceptionComSpecProps</code> sowie E2E-Transformationsparameter greifen optional und konfigurieren die Überwachungsmechanismen für das assoziierte <code>dataElement</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9cfa446ca6dd0a53", "to": "FIG-f636d33343098610", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Doppelpunkt-Typabstände in Attributen vereinheitlicht (z. B. <code>+ dataUpdatePeriod: TimeValue [0..1]</code>).\n</li><li>Trennlinie in der Klassenbox <code>AutosarDataPrototype</code> zwischen Stereotyp/Klassenname und Attributbereich eingefügt.\n</li></ul>"}, {"from": "FIG-f636d33343098610", "to": "FIG-4949615ec489d73e", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>EndToEndTransformationComSpecProps</code> Attribut <code>windowSize: PositiveInteger [0..1]</code> ersetzt durch zustandsspezifische Fenstergrößen <code>windowSizeInit: PositiveInteger [0..1]</code>, <code>windowSizeInvalid: PositiveInteger [0..1]</code> und <code>windowSizeValid: PositiveInteger [0..1]</code>.\n</li><li>In Klasse <code>EndToEndTransformationComSpecProps</code> Attribut <code>clearFromValidToInvalid: Boolean [0..1]</code> ergänzt.\n</li></ul>"}, {"from": "FIG-4949615ec489d73e", "to": "FIG-13d52517bc4b754e", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>ReceiverComSpec</code> Attribute <code>dataUpdatePeriod</code> und <code>receiverCapability</code> entfernt; Enumeration <code>ReceiverCapabilityEnum</code> ersetzt durch <code>ReceiverIntentEnum</code> (<code>willReceive</code>, <code>wontReceive</code>) und neues Attribut <code>+ receiverIntent: ReceiverIntentEnum [0..1]</code> eingeführt.\n</li><li>In Klasse <code>QueuedReceiverComSpec</code> Kardinalität von <code>queueLength</code> von obligatorisch <code>1</code> auf optional <code>[0..1]</code> geändert.\n</li><li>In Klasse <code>EndToEndTransformationComSpecProps</code> Kardinalität von <code>disableEndToEndCheck</code> von obligatorisch <code>Boolean</code> auf optional <code>Boolean [0..1]</code> geändert.\n</li><li>In Klasse <code>EndToEndTransformationComSpecProps</code> Attribut <code>disableEndToEndStateMachine: Boolean [0..1]</code> ergänzt.\n</li><li>Neue Spezialisierungsklasse <code>UserDefinedTransformationComSpecProps</code> unter <code>TransformationComSpecProps</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-13d52517bc4b754e", "to": "FIG-cba953bf12096b0c", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>QueuedReceiverComSpec</code> Attribut <code>queueLength</code> entfernt.\n</li><li>Neue Klasse <code>ReceptionComSpecProps</code> mit Attributen <code>+ dataUpdatePeriod: TimeValue [0..1]</code> und <code>+ timeout: TimeValue [0..1]</code> hinzugefügt.\n</li><li>Komposition <code>+receptionProps 0..1</code> von <code>ReceiverComSpec</code> auf <code>ReceptionComSpecProps</code> eingeführt.\n</li></ul>"}, {"from": "FIG-cba953bf12096b0c", "to": "FIG-04f47afcf82a5716", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-04f47afcf82a5716", "to": "FIG-49c3b18141e0759b", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotyp <code>«atpSplitable»</code> an der Kompositionsbeziehung <code>requiredComSpec</code> zwischen <code>AbstractRequiredPortPrototype</code> und <code>RPortComSpec</code> ergänzt.\n</li><li>Diagrammlayout horizontal umarrangiert.\n</li></ul>"}, {"from": "FIG-49c3b18141e0759b", "to": "FIG-5e5d9750141e93df", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>ReceiverIntentEnum</code>: Das Enum-Feld wurde nach unten verschoben und enthält nun die standardmäßige UML-Abschnittsüberschrift <em>literals</em> über den Literalen <code>willReceive</code> und <code>wontReceive</code>.\n</li></ul>"}, {"from": "FIG-5e5d9750141e93df", "to": "FIG-638d3e8d088afa49", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Rolle <code>+dataElement</code> (an <code>AutosarDataPrototype</code>): Stereotyp <code>«atpIdentityContributor»</code> ergänzt.\n</li><li>Rolle <code>+transformationComSpecProps</code> (an <code>TransformationComSpecProps</code>): Stereotyp <code>«atpSplitable»</code> ergänzt.\n</li></ul>"}]};
